  /*
   * Best-effort: capture ev_referral to sessionStorage if present.
   * Some themes/scripts overwrite the URL (e.g. adding variant), which strips ev_referral
   * before our activate script runs. If this inline runs first, sessionStorage preserves it.
   * Timing depends on block placement and theme; stores that don't modify the URL
   * will have ev_referral in the URL when the activate script runs - no fallback needed.
   */
  (function () {
    var m = location.search.match(/[?&]ev_referral=([^&\s#]+)/);
    if (m) try { sessionStorage.setItem('EV.ev_referral', m[1]); } catch (e) {}
  })();
